CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY,name VARCHAR(255) NOT NULL,email VARCHAR(255) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,role VARCHAR(20) DEFAULT 'customer',created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS foods (id SERIAL PRIMARY KEY,name VARCHAR(255) NOT NULL,price DECIMAL(10,2) NOT NULL,category VARCHAR(100) NOT NULL,description TEXT,image VARCHAR(500),rating DECIMAL(3,2) DEFAULT 4.5,addons JSONB DEFAULT '[]',created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS orders (id SERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,items JSONB NOT NULL,total DECIMAL(10,2) NOT NULL,address TEXT NOT NULL,phone VARCHAR(20),notes TEXT,status VARCHAR(50) DEFAULT 'pending',created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS surveys (id SERIAL PRIMARY KEY,title VARCHAR(255) NOT NULL,questions JSONB NOT NULL,created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS survey_responses (id SERIAL PRIMARY KEY,survey_id INTEGER REFERENCES surveys(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,answers JSONB NOT NULL,created_at TIMESTAMP DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_foods_category ON foods(category); CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status); CREATE INDEX IF NOT EXISTS idx_orders_user ON orders(user_id);
